package com.loadoutstudio;
import com.google.gson.*;import java.awt.*;import java.util.*;import java.util.function.Consumer;import javax.swing.*;import javax.swing.border.LineBorder;import net.runelite.http.api.RuneLiteAPI;import org.junit.Test;import static org.junit.Assert.*;
public class SettingsBehaviorAuditTest {
 static class Settings implements LoadoutStudioConfig {
  boolean on,attack=true,automatic=false,expand=true,stock=true,empty=true,diagnostic=true;int maximum=3;StackRule rule=StackRule.MINIMUM;
  public boolean defaultHighlight(){return on;}public boolean defaultFilterBank(){return on;}public boolean defaultMissingOnly(){return on;}public boolean defaultFuzzy(){return on;}
  public Color defaultHighlightColor(){return Color.CYAN;}public DefaultLayout defaultLayout(){return DefaultLayout.ZIGZAG;}public boolean defaultZigzagBottom(){return true;}public StackRule defaultStackRule(){return rule;}
  public boolean captureAttackOption(){return on;}public boolean showAttackOption(){return attack;}public boolean autoAlternatives(){return automatic;}public boolean autoShowAlternatives(){return expand;}public int maxAlternatives(){return maximum;}
  public boolean checkAlternativeStock(){return stock;}public boolean emptyQuantityInput(){return empty;}
  public boolean localDiagnostics(){return diagnostic;}
 }
 static class Host extends PanelTest.FakeHost {
  final Settings settings=new Settings();Consumer<Integer> choose;Consumer<OwnedGear> pending;
  public LoadoutStudioConfig settings(){return settings;}public StudioPanel.ItemInfo defaultItem(String n){return new StudioPanel.ItemInfo(385,n,false,-1,null);}
  public void chooseItem(Consumer<Integer> selected,Consumer<String> error){choose=selected;}public void describe(int id,Consumer<StudioPanel.ItemInfo> selected){selected.accept(new StudioPanel.ItemInfo(id,"Shark",false,-1,null));}
  public void availableGear(JsonObject p,Consumer<OwnedGear> success,Consumer<String> error){pending=success;}
 }
 static JsonObject source(){JsonObject p=SetupCodec.blank("Wiki defaults");JsonObject i=SetupCodec.item(385,1);i.addProperty("label","Shark");SetupCodec.setup(p).getAsJsonArray("inv").set(0,i);SetupCodec.setup(p).addProperty("ao","Stab");SetupCodec.rebuildLayout(p);return p;}
 static SetupLibrary.Entry saved(StudioPanel panel,Host h){OwnedGearPanelTest.click(panel,"Save");return SetupLibrary.read(h.saved,RuneLiteAPI.GSON).setups.get(0);}
 static JButton slot(Container c){for(Component x:c.getComponents()){if(x instanceof JButton&&"inv".equals(((JButton)x).getClientProperty("slotContainer"))&&Integer.valueOf(0).equals(((JButton)x).getClientProperty("slotIndex")))return (JButton)x;if(x instanceof Container){JButton b=slot((Container)x);if(b!=null)return b;}}return null;}
 @Test public void creationDefaultsRespectBothBooleanValuesEveryAmountRuleAndCaptureScope(){
  for(boolean on:new boolean[]{false,true})for(LoadoutStudioConfig.StackRule rule:LoadoutStudioConfig.StackRule.values()){Settings s=new Settings();s.on=on;s.rule=rule;JsonObject input=source(),before=input.deepCopy();JsonObject created=SetupCodec.setup(LoadoutDefaults.created(input,s)),captured=SetupCodec.setup(LoadoutDefaults.captured(input,s));for(JsonObject setup:Arrays.asList(created,captured)){for(String flag:new String[]{"hd","fb","uh"})assertEquals(on,setup.get(flag).getAsBoolean());assertEquals("#FF00FFFF",setup.get("hc").getAsString());JsonObject item=setup.getAsJsonArray("inv").get(0).getAsJsonObject();assertEquals(on,item.get("f").getAsBoolean());assertEquals(rule.code,item.get("sc").getAsString());}assertTrue(created.has("ao"));assertEquals(on,captured.has("ao"));assertEquals(before,input);}
 }
 @Test public void actualWikiOpenUsesDefaultsAndDoesNotPaintDisabledHighlights()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject original=source(),before=original.deepCopy();p.openWikiPreset(original);p.acceptLiveGear(SetupCodec.blank("Actual"));assertEquals(StudioTheme.BACKGROUND,((LineBorder)slot(p).getBorder()).getLineColor());SetupLibrary.Entry entry=saved(p,h);JsonObject s=SetupCodec.setup(entry.portable);assertFalse(s.get("hd").getAsBoolean());assertFalse(s.get("fb").getAsBoolean());assertEquals("#FF00FFFF",s.get("hc").getAsString());assertEquals(BankLayouts.Mode.ZIGZAG,entry.bankLayout);assertTrue(entry.zigzagBottomToTop);assertEquals(before,original);p.dispose();});}
 @Test public void savedAndExplicitlyImportedSetupsKeepTheirOwnHighlighting()throws Exception{SwingUtilities.invokeAndWait(()->{for(boolean saved:new boolean[]{false,true}){Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject input=source();SetupCodec.setup(input).addProperty("hd",true);if(saved)p.open(new SetupLibrary.Entry(input));else p.newDraft(input);p.preferencesChanged();assertTrue(SetupCodec.setup(saved(p,h).portable).get("hd").getAsBoolean());p.dispose();}});}
 @Test public void liveAttackOptionPreferenceRefreshesWithoutLosingNotesOrCaret()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.newDraft(source());JTextArea notes=(JTextArea)OwnedGearPanelTest.find(p,"loadoutNotes");notes.setText("Keep these notes");notes.setCaretPosition(4);h.settings.attack=false;p.preferencesChanged();assertNull(OwnedGearPanelTest.find(p,"Attack option: Stab"));assertEquals(4,notes.getCaretPosition());assertEquals("Keep these notes",notes.getText());h.settings.attack=true;p.preferencesChanged();assertNotNull(OwnedGearPanelTest.find(p,"Attack option: Stab"));p.dispose();});}
 @Test public void switchingOffAutomaticAlternativesRejectsPendingResultsAndManualCapUpdates()throws Exception{SwingUtilities.invokeAndWait(()->{
  Host h=new Host();h.settings.automatic=true;StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.newDraft(OwnedGearTest.setup());p.refreshAlternatives();Consumer<OwnedGear> old=h.pending;h.settings.automatic=false;p.preferencesChanged();old.accept(OwnedGearTest.gear(3,4));assertNull(OwnedGearPanelTest.find(p,"ownedChoice:eq:4"));assertNotNull(OwnedGearPanelTest.find(p,"Refresh alternatives"));
  Map<Integer,Integer> amounts=new LinkedHashMap<>();Map<Integer,StudioPanel.ItemInfo> items=new LinkedHashMap<>();items.put(1,OwnedGearTest.item(1,"Torva platebody",4));String[] names={"Bandos chestplate","Fighter torso","Obsidian platebody"};for(int i=0;i<3;i++){amounts.put(i+2,5);items.put(i+2,OwnedGearTest.item(i+2,names[i],4));}OwnedGear gear=new OwnedGear(amounts,items,1,true);
  for(int max:new int[]{1,3}){h.settings.maximum=max;p.preferencesChanged();p.refreshAlternatives();h.pending.accept(gear);assertEquals(max+1,((JComboBox<?>)OwnedGearPanelTest.find(p,"ownedChoice:eq:4")).getItemCount());}h.settings.expand=false;p.preferencesChanged();assertEquals("+ My gear alternatives",((JButton)OwnedGearPanelTest.find(p,"disclosure:My gear alternatives")).getText());p.dispose();
 });}
 @Test public void newManualSlotsUseDefaultsAndReplacementPreservesTheirRules()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();h.settings.on=true;h.settings.rule=LoadoutStudioConfig.StackRule.NONE;StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.newDraft(SetupCodec.blank("New slots"));slot(p).doClick();h.choose.accept(385);JsonObject item=SetupCodec.setup(saved(p,h).portable).getAsJsonArray("inv").get(0).getAsJsonObject();assertTrue(item.get("f").getAsBoolean());assertEquals("None",item.get("sc").getAsString());h.settings.on=false;h.settings.rule=LoadoutStudioConfig.StackRule.MAXIMUM;slot(p).doClick();h.choose.accept(385);JsonObject replacement=SetupCodec.setup(saved(p,h).portable).getAsJsonArray("inv").get(0).getAsJsonObject();assertTrue(replacement.get("f").getAsBoolean());assertEquals("None",replacement.get("sc").getAsString());p.dispose();});}
 @Test public void stockCheckboxControlsTheActualApplyActionImmediately()throws Exception{SwingUtilities.invokeAndWait(()->{
  class StockHost extends Host {public void availableGear(JsonObject p,Consumer<OwnedGear> success,Consumer<String> error){success.accept(OwnedGearTest.gear(1,4));}}
  StockHost h=new StockHost();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject input=OwnedGearTest.setup();SetupCodec.setup(input).getAsJsonArray("inv").set(0,SetupCodec.item(1,1));SetupCodec.rebuildLayout(input);p.newDraft(input);p.refreshAlternatives();for(String name:new String[]{"ownedChoice:eq:4","ownedChoice:inv:0"})((JComboBox<?>)OwnedGearPanelTest.find(p,name)).setSelectedIndex(1);
  OwnedGearPanelTest.click(p,"Use selected alternatives");assertEquals(1,SetupCodec.id(SetupCodec.setup(h.selectedBankSetup).getAsJsonArray("eq").get(4)));h.settings.stock=false;OwnedGearPanelTest.click(p,"Use selected alternatives");assertEquals(2,SetupCodec.id(SetupCodec.setup(h.selectedBankSetup).getAsJsonArray("eq").get(4)));p.dispose();
 });}
 @Test public void emptyQuantitySettingControlsBothInputStatesWithoutChangingTheItem()throws Exception{SwingUtilities.invokeAndWait(()->{
  class QuantityHost extends Host {String initial;public void describe(int id,Consumer<StudioPanel.ItemInfo> done){done.accept(new StudioPanel.ItemInfo(id,"Nature rune",true,-1,null));}public void enterQuantity(String value,Consumer<String> chosen,Consumer<String> error){initial=value;}}
  QuantityHost h=new QuantityHost();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject input=SetupCodec.blank("Amount input");SetupCodec.setup(input).getAsJsonArray("inv").set(0,SetupCodec.item(561,16000));SetupCodec.rebuildLayout(input);p.newDraft(input);for(boolean empty:new boolean[]{true,false}){h.settings.empty=empty;slot(p).doClick();h.choose.accept(561);assertEquals(empty?"":"16000",h.initial);}assertEquals(16000,SetupCodec.quantity(SetupCodec.setup(saved(p,h).portable).getAsJsonArray("inv").get(0)));p.dispose();
 });}
 @Test public void diagnosticsOffClearsAndStopsRecordingImmediately()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.newDraft(source());saved(p,h);assertTrue(p.diagnosticReport().contains("SAVE: calls="));h.settings.diagnostic=false;p.preferencesChanged();assertTrue(p.diagnosticReport().contains("Recording: disabled"));assertTrue(p.diagnosticReport().contains("No samples."));saved(p,h);assertTrue(p.diagnosticReport().contains("No samples."));p.dispose();});}
 @Test public void profileReloadAlsoReadsDiagnosticsAndStopsPreviousAlternativeState()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.newDraft(source());saved(p,h);h.settings.diagnostic=false;h.settings.expand=false;h.scope="character-two";p.reloadScope();assertTrue(p.diagnosticReport().contains("Recording: disabled"));assertTrue(p.diagnosticReport().contains("No samples."));p.dispose();});}
}
